package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Real 6717 frames; acknowledgements, modified pixels and alternate geometry are synthetic. */
public final class Video6717ReplayTest {
 static final String P=ShoppingPreset.P;static int checks;static Map<String,float[]> refs;static final Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();
 static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static void load()throws Exception{refs=VirtualPresetProfileTest.canonical("tests/video6717-references.bin");try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6717-replay.bin.gz")))){int n=in.readInt();for(int i=0;i<n;i++)images.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));check(n==49&&in.read()==-1,"complete held-out recording fixture");}}
 static final class Run {
  final PhaseEngine e=new PhaseEngine();final ShoppingLayout layout;final AdExitPolicy exits=new AdExitPolicy();Map<String,float[]> samples;
  Run(String state){ShoppingPreset.install(e,refs);e.strictRuntime=true;layout=ShoppingLayout.install(e,refs);AdCloseAutomaton.install(e,ShoppingPreset.APP);e.enter(P+state,0);check(layout!=null&&e.validate().isEmpty(),"runtime graph is valid");}
  PhaseEngine.Watch observe(int w,int h,RegionSampler.Pixels pixels,long now,int[] window){samples=layout.sampleRelative(e.activeRegions(),w,h,pixels,now,window);exits.filter(e,samples,w,h,now,now);e.observe(samples,now);return e.poll();}
  PhaseEngine.Watch event(String id){VirtualPresetProfileTest.Image im=images.get(id);check(observe(im.width,im.height,im,1000,null)==null,"first observation cannot commit "+e.current+" / "+id);return observe(im.width,im.height,im,1350,null);}
  float[] point(PhaseEngine.Watch w,String id){VirtualPresetProfileTest.Image im=images.get(id);return layout.pointRelative(w,samples,im.width,im.height);}
 }
 static void home(){
  for(String id:new String[]{"0","3","40","44","82","90","120","154","156","164","166","0-native"}){
   Run r=new Run("verify");PhaseEngine.Watch w=r.event(id);check(w!=null&&w.action==PhaseEngine.WAIT&&w.nextPhase.equals(P+"main"),"unobstructed landmarks confirm actual home: "+id+" / "+r.e.diagnostic);r.e.finish(w,1400);check(ShoppingPreset.playable(r.e,r.samples),"confirmed home enables normal play");VirtualPresetProfileTest.Image im=images.get(id);float[] p=r.layout.mainPointRelative(r.samples,im.width,im.height);check(p!=null&&Math.abs(p[0]/im.width-.5)<.025&&p[1]/im.height>.70&&p[1]/im.height<.75,"main point stays inside the actual pink carry button");
  }
  for(String id:new String[]{"40","44","82","90","120","154","156","164"}){Run r=new Run("main");PhaseEngine.Watch w=r.event(id);check(w==null||!w.id.equals(P+"boost-button"),"visible active timer prevents unnecessary boost renewal: "+id);}
 }
 static void resume(){
  for(String state:new String[]{"check","main","ad","reward-ad","mission-ad","mission-opening"})for(String id:new String[]{"80","116","118","170","118-native","170-native"}){
   Run r=new Run(state);PhaseEngine.Watch w=r.event(id);check(w!=null&&w.action==PhaseEngine.CENTER&&w.regionId.equals(ShoppingResumePolicy.REGION)&&w.nextPhase.equals(P+"verify"),"bonus resumes without CM from "+state+" / "+id);float[] p=r.point(w,id);VirtualPresetProfileTest.Image im=images.get(id);boolean small=id.startsWith("170");check(p!=null&&p[0]/im.width>(small?.55:.595)&&p[0]/im.width<(small?.65:.73)&&p[1]/im.height>(small?.61:.697)&&p[1]/im.height<(small?.64:.73),"resume point is on the right side of its own label, below CM and away from marker");
   Map<String,float[]> fresh=r.layout.sampleRelative(ScanPlan.select(r.e,w.regionId,false),im.width,im.height,im,1450);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"input preflight rechecks the actual resume card");check(r.layout.pointRelative(w,fresh,im.width+1,im.height)==null,"resized frame cannot reuse a resume coordinate");
   VirtualPresetProfileTest.Image ad=images.get("75");fresh=r.layout.sampleRelative(ScanPlan.select(r.e,w.regionId,false),ad.width,ad.height,ad,1600);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh)&&r.layout.pointRelative(w,fresh,ad.width,ad.height)==null,"card disappearance cancels the old coordinate");
  }
 }
 static void rewardsAndMissions(){
  for(String id:new String[]{"95.2","95.5","167.5","167.7"}){Run r=new Run("reward");PhaseEngine.Watch w=r.event(id);float[] p=w==null?null:r.point(w,id);VirtualPresetProfileTest.Image im=images.get(id);check(w!=null&&w.id.equals(P+"reward-close")&&w.action==PhaseEngine.CENTER&&p!=null&&p[0]/im.width>.42&&p[0]/im.width<.59&&p[1]/im.height>.54&&p[1]/im.height<.59,"close is confirmed below the panel without reading its covered heading: "+id);check(w.nextPhase.equals(P+"mission-opening"),"reward close keeps mission continuation");}
  for(String[] row:new String[][]{{"94","get-tap"},{"78","mission-play"},{"95.8","mission-play"},{"96","mission-play"}}){Run r=new Run("missions");PhaseEngine.Watch w=r.event(row[0]);float[] p=w==null?null:r.point(w,row[0]);VirtualPresetProfileTest.Image im=images.get(row[0]);check(w!=null&&w.id.equals(P+row[1])&&w.action==PhaseEngine.CENTER&&p!=null&&p[0]/im.width>.776&&p[0]/im.width<.87&&p[1]/im.height>.39&&p[1]/im.height<.43,"visible right-hand mission label selects its actual Get or Play: "+Arrays.toString(row)+" / "+r.e.diagnostic);Map<String,float[]> fresh=r.layout.sampleRelative(ScanPlan.select(r.e,w.regionId,false),im.width,im.height,im,1500);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"mission input preflight keeps heading dependency");}
  Run r=new Run("boost");PhaseEngine.Watch w=r.event("122");float[] p=w==null?null:r.point(w,"122");VirtualPresetProfileTest.Image im=images.get("122");check(w!=null&&w.id.equals(P+"boost-yes")&&w.nextPhase.equals(P+"reward-ad")&&p!=null&&p[0]/im.width>.45&&p[0]/im.width<.56&&p[1]/im.height>.60&&p[1]/im.height<.64,"existing shopping boost policy uses its own visible body and Yes, never the resume label");
 }
 static void advertisements(){
  for(String state:new String[]{"check","ad","reward-ad","mission-ad"})for(String id:new String[]{"73","75","73-native"}){Run r=new Run(state);PhaseEngine.Watch w=r.event(id);float[] p=w==null?null:r.point(w,id);VirtualPresetProfileTest.Image im=images.get(id);check(w!=null&&w.regionId.equals(AdCloseAutomaton.RIGHT)&&w.action==PhaseEngine.CENTER&&p!=null&&p[0]/im.width>.89&&p[0]/im.width<.94&&p[1]/im.height>.06&&p[1]/im.height<.09,"plain white arrow is recognized in the observed black ad band: "+state+" / "+id);Map<String,float[]> fresh=r.layout.sampleRelative(ScanPlan.select(r.e,w.regionId,false),im.width,im.height,im,1500);check(r.exits.preflight(w,fresh,im.width,im.height)&&r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"arrow preflight preserves the chosen exit");}
  for(String id:new String[]{"5","34","58","70","112","126","171","174","180","182","183"}){VirtualPresetProfileTest.Image im=images.get(id);check(AdPlainArrowDetector.find(im.width,im.height,false,im).isEmpty(),"playing ad, CTA, pale badge, or store is not the observed black-band arrow: "+id);Run r=new Run("verify");r.event(id);check(!ShoppingPreset.playable(r.e,r.samples)&&!r.samples.containsKey(AdaptiveLayout.MAIN),"ad/store frame never provides a normal-play point: "+id);}
  VirtualPresetProfileTest.Image im=images.get("73");Map<String,float[]> candidates=new HashMap<>();candidates.put(AdCloseAutomaton.RIGHT,new float[]{1});candidates.put(AdCloseAutomaton.RIGHT+AdCloseAutomaton.POINT,new float[]{im.width*.82f,im.height*.07f});AdCloseAutomaton.word(AdCloseAutomaton.RIGHT,im.width,im.height,im,candidates);check(AdCloseAutomaton.candidates(AdCloseAutomaton.RIGHT,candidates,im.width,im.height).size()==2,"arrow is retained alongside an already verified exit in the same corner");
 }
 static void missingLandmarks(){
  VirtualPresetProfileTest.Image im=images.get("118");float[][] anchors=ShoppingControlEvidence.anchors("resume");
  for(int part=0;part<3;part++){Run r=new Run("check");final int mode=part;int[] cut=RegionMath.bounds(anchors[Math.min(part,1)],im.width,im.height);RegionSampler.Pixels altered=(x,y)->{int c=im.get(x,y);if(mode==2)return 0xff000000|((c>>16&255)/2)<<16|((c>>8&255)/2)<<8|(c&255)/2;return x>=cut[0]-3&&x<cut[2]+3&&y>=cut[1]-3&&y<cut[3]+3?0xff777777:c;};r.observe(im.width,im.height,altered,1000,null);PhaseEngine.Watch w=r.observe(im.width,im.height,altered,1350,null);check(w==null||!w.regionId.equals(ShoppingResumePolicy.REGION),"missing body, missing own label or dimmed card blocks resume");check(!r.samples.containsKey(ShoppingResumePolicy.REGION+AdaptiveLayout.BOUNDS),"unproved card supplies no input coordinate");}
  Run r=new Run("verify");VirtualPresetProfileTest.Image home=images.get("0");int[] b=RegionMath.bounds(ShoppingControlEvidence.HOME_LABEL,home.width,home.height);RegionSampler.Pixels missing=(x,y)->x>=b[0]-2&&x<b[2]+2&&y>=b[1]-2&&y<b[3]+2?0xff27333f:home.get(x,y);r.observe(home.width,home.height,missing,1000,null);r.observe(home.width,home.height,missing,1350,null);check(!ShoppingPreset.playable(r.e,r.samples)&&r.e.rule(P+"verify-home").distance(r.samples.get(P+"home"))>r.e.rule(P+"verify-home").threshold,"header alone cannot authorize normal tapping when the independent lower landmark is missing");
 }
 static void geometryAndOwnership(){
  for(String id:new String[]{"0-native","118-native","170-native","73-native"})for(boolean smooth:new boolean[]{false,true}){
   VirtualPresetProfileTest.Image im=images.get(id);Run r=new Run(id.startsWith("0-")?"verify":"ad");RegionSampler.Pixels pixels=FarmDialogReplayTest.resize(im,720,1616,smooth);r.observe(720,1616,pixels,1000,null);PhaseEngine.Watch w=r.observe(720,1616,pixels,1350,null);check(w!=null,"observed scene survives preview scaling: "+id+" / "+smooth);if(!id.startsWith("0-"))check(r.layout.pointRelative(w,r.samples,720,1616)!=null,"scaled action has a fresh point");
  }
  VirtualPresetProfileTest.Image im=images.get("118");int width=1200,height=1500,left=280,top=80;RegionSampler.Pixels moved=(x,y)->x>=left&&x<left+im.width&&y>=top&&y<top+im.height?im.get(x-left,y-top):0xff384858;Run r=new Run("check");r.observe(width,height,moved,1000,new int[]{left,top,left+im.width,top+im.height});PhaseEngine.Watch w=r.observe(width,height,moved,1350,new int[]{left,top,left+im.width,top+im.height});float[] p=w==null?null:r.layout.pointRelative(w,r.samples,width,height);check(w!=null&&w.regionId.equals(ShoppingResumePolicy.REGION)&&p!=null&&p[0]>left+im.width*.59&&p[0]<left+im.width*.73&&p[1]>top+im.height*.697&&p[1]<top+im.height*.73,"application window offset is applied exactly once to resume");
  PhaseEngine old=ShoppingPreset.version182Defaults(refs),fresh=new PhaseEngine();ShoppingPreset.install(fresh,refs);check(ShoppingPreset.upgrade(old,refs)&&AutomatonGraph.sameConfiguration(old,fresh)&&!ShoppingPreset.upgrade(old,refs),"standard saved shopping graph upgrades completely and only once");PhaseEngine edited=ShoppingPreset.version182Defaults(refs);edited.rule(P+"reward-close").action=PhaseEngine.STOP;check(!ShoppingPreset.upgrade(edited,refs)&&!edited.regions.containsKey(ShoppingResumePolicy.REGION),"custom saved actions are not overwritten or given new resume arrows");
  edited=fresh.runtimeCopy();edited.rule(P+"verify-home").threshold=.001f;ShoppingLayout layout=ShoppingLayout.install(edited,refs);edited.enter(P+"verify",0);Map<String,float[]> samples=layout.sampleRelative(edited.activeRegions(),images.get("0").width,images.get("0").height,images.get("0"),1000);check(!edited.rule(P+"verify-home").runtimeControlEvidence&&edited.rule(P+"verify-home").distance(samples.get(P+"home"))>.001f,"custom tighter home tolerance cannot accept factory binary proof");
  edited=fresh.runtimeCopy();PhaseEngine.Watch custom=edited.rule(P+"check-resume-without-cm");custom.reference=new float[768];custom.threshold=.004f;layout=ShoppingLayout.install(edited,refs);edited.enter(P+"check",0);samples=layout.sampleRelative(edited.activeRegions(),images.get("118").width,images.get("118").height,images.get("118"),1000);check(!layout.resumeDefault&&samples.get(ShoppingResumePolicy.REGION).length==768,"a user-recorded resume image keeps raw region sampling instead of factory binary proof");
  r=new Run("main");VirtualPresetProfileTest.Image home=images.get("40"),card=images.get("118");r.observe(home.width,home.height,home,1000,null);r.observe(home.width,home.height,home,1350,null);check(r.samples.containsKey(P+"home"+AdaptiveLayout.BOUNDS),"normal play can use its confirmed home without searching the bonus card");check(r.observe(card.width,card.height,card,1600,null)==null,"a newly shown card holds main input on its first observation");w=r.observe(card.width,card.height,card,1950,null);check(w!=null&&w.regionId.equals(ShoppingResumePolicy.REGION),"the prior confirmed home cannot hide the next fresh bonus card");
 }
 public static void main(String[] args)throws Exception{load();home();resume();rewardsAndMissions();advertisements();missingLandmarks();geometryAndOwnership();System.out.println("Video6717ReplayTest: "+checks+" checks passed; held-out shopping home/resume/reward/mission/boost and ad-arrow pixels, guarded input, migration and synthetic negatives/geometry; new APK physical execution untested");}
}
